async function analyzeTokenSentiment(tokenSymbol, tokenName, context = {}) {
  const client = getClient();
  if (!client) {
    return {
      verdict: "UNKNOWN",
      confidence: 0,
      summary: "AI analyst offline \u2014 OPENROUTER_API_KEY not configured.",
      usedAi: false
    };
  }
  const contextLines = [];
  if (context.liquidityUsd !== void 0) contextLines.push(`- Liquidity: $${context.liquidityUsd.toLocaleString()}`);
  if (context.volume24h !== void 0) contextLines.push(`- 24h Volume: $${context.volume24h.toLocaleString()}`);
  if (context.priceChangePercent24h !== void 0) contextLines.push(`- 24h Price Change: ${context.priceChangePercent24h.toFixed(2)}%`);
  if (context.holderCount !== void 0) contextLines.push(`- Holder Count: ${context.holderCount}`);
  if (context.topHolderPct !== void 0) contextLines.push(`- Top 10 Holders: ${context.topHolderPct.toFixed(1)}%`);
  if (context.isNew) contextLines.push(`- Token is NEW (launched within last hour)`);
  if (context.isTrending) contextLines.push(`- Appearing on DEX Screener trending list`);
  if (context.isBoosted) contextLines.push(`- Has active DEX Screener boost`);
  const prompt = `You are a meme coin trading analyst. Analyze this Solana token and give a sentiment verdict.

Token: ${tokenSymbol} (${tokenName})
${contextLines.join("\n")}

Respond with JSON only:
{
  "verdict": "BULLISH" | "BEARISH" | "NEUTRAL",
  "confidence": 0-100,
  "summary": "one sentence reasoning"
}`;
  try {
    const completion = await client.chat.completions.create({
      model: "meta-llama/llama-3.1-8b-instruct:free",
      messages: [{ role: "user", content: prompt }],
      response_format: { type: "json_object" },
      max_tokens: 150
    });
    const raw = completion.choices[0]?.message?.content ?? "{}";
    const parsed = JSON.parse(raw);
    return {
      verdict: parsed.verdict ?? "NEUTRAL",
      confidence: parsed.confidence ?? 50,
      summary: parsed.summary ?? "No summary provided.",
      rawResponse: raw,
      usedAi: true
    };
  } catch (err) {
    logger.error({ err, tokenSymbol }, "AI analyst request failed");
    return {
      verdict: "UNKNOWN",
      confidence: 0,
      summary: "AI analysis failed.",
      usedAi: false
    };
  }
}

